function largeGroupPositions(s) {
  const result = [];
  let start = 0;
  for (let end = 0; end < s.length; end++) {
    const lastOfRun = end === s.length - 1 || s[end] !== s[end + 1];
    if (lastOfRun) {
      if (end - start + 1 >= 3) {
        result.push([start, end]);
      }
      start = end + 1;
    }
  }
  return result;
}

