function largeGroupPositions(s) {
  // A regular expression finds every letter repeated at least three times in a row.
  const result = [];
  for (const match of s.matchAll(/([a-z])\1{2,}/g)) {
    result.push([match.index, match.index + match[0].length - 1]);
  }
  return result;
}

