function generate(rand, size) {
  const target = size === 'large' ? 950 + Math.floor(rand() * 51) : 1 + Math.floor(rand() * 25);
  const letters = rand() < 0.5 ? 2 : 4;
  const longest = rand() < 0.5 ? 5 : 12;
  let s = '';
  while (s.length < target) {
    const letter = String.fromCharCode(97 + Math.floor(rand() * letters));
    const run = 1 + Math.floor(rand() * longest);
    s += letter.repeat(run);
  }
  return [s.slice(0, target)];
}
